xql_query:
// ============================================================
// Rule: REPORT-FTG_Successful RDP
// Vendor: Fortigate
// Objective:
// Detect activity associated with REPORT-FTG_Successful RDP.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================

dataset = fortinet_fortigate_raw
| filter app = "RDP"
| filter act = "accept"
| alter 
    host = shost,
    timestamp = _time,
    src_ip = src,
    dst_ip = dst,
    action_taken = act,
    log_message = msg,
    device_name = _reporting_device_name
| fields timestamp, device_name, src_ip, dst_ip, action_taken, log_message
